class DistributedProcess:
    def __init__(self, pid: str, state: int, incoming_channels: list[str], outgoing_channels: list[str]):
        self.pid = pid
        self.state = state
        self.incoming = incoming_channels
        self.outgoing = outgoing_channels
        self.has_snapshotted = False
        self.saved_state = None
        self.channel_snapshots = {}
        self.recording_channels = set()

    def start_snapshot(self) -> list[tuple[str, str]]:
        self.has_snapshotted = True
        self.saved_state = self.state
        for ch in self.incoming:
            self.channel_snapshots[ch] = []
            self.recording_channels.add(ch)
        return [(ch, "MARKER") for ch in self.outgoing]

    def receive_marker(self, channel_id: str) -> list[tuple[str, str]]:
        if not self.has_snapshotted:
            self.has_snapshotted = True
            self.saved_state = self.state
            for ch in self.incoming:
                self.channel_snapshots[ch] = []
                if ch != channel_id:
                    self.recording_channels.add(ch)
            return [(ch, "MARKER") for ch in self.outgoing]
        else:
            if channel_id in self.recording_channels:
                self.recording_channels.remove(channel_id)
            return []

    def receive_message(self, channel_id: str, msg: str) -> None:
        # Apply message effect to state (parse integer delta if present)
        if msg.startswith("+"):
            self.state += int(msg[1:])
        elif msg.startswith("-"):
            self.state -= int(msg[1:])

        if channel_id in self.recording_channels:
            self.channel_snapshots[channel_id].append(msg)

    def get_snapshot(self) -> dict:
        return {
            "state": self.saved_state,
            "channels": {k: list(v) for k, v in self.channel_snapshots.items()}
        }
